import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Find features with significant difference in means between outcome groups
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression', 'clinical'):
            group0 = feats.x[feats.y == 0, i]
            group1 = feats.x[feats.y == 1, i]
            tstat, pval = stats.ttest_ind(group0, group1, equal_var=False)
            if pval < 0.05 and abs(tstat) > 1.5:
                sig_features.append((fid, tstat, pval))

    # Sort by effect size
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for product terms
    candidates = [f[0] for f in sig_features[:10]]  # Top 10 features

    # Remove near-duplicates based on correlation
    keep = []
    used = set()
    for a in candidates:
        if a in used:
            continue
        keep.append(a)
        for b in candidates:
            if a != b and b not in used:
                col_a = feats.column(a)
                col_b = feats.column(b)
                if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]) > 0.6:
                    used.add(b)

    # Try pairwise interactions
    best_score = -np.inf
    best_pair = None

    for i, a in enumerate(keep):
        for j, b in enumerate(keep[i+1:], i+1):
            # Create interaction term
            col_a = feats.column(a)
            col_b = feats.column(b)
            interaction = feats.x[:, col_a] * feats.x[:, col_b]

            # Fit logistic regression with both main effects and interaction
            X = np.column_stack([feats.x[:, col_a], feats.x[:, col_b], interaction])
            model = LogisticRegression(fit_intercept=True, max_iter=1000)
            model.fit(X, feats.y)
            score = model.score(X, feats.y)

            if score > best_score:
                best_score = score
                best_pair = (a, b)

    # Return result
    if best_pair:
        return Design(
            drivers=(best_pair[0], best_pair[1]),
            columns=(best_pair[0], best_pair[1]),
            products=(best_pair,),
            loadings={}
        )
    else:
        # No strong interaction found, return empty design
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

